<?php
session_start();
require '../../config/db.php';
if (!isset($_SESSION['admin_id'])) { header('Location: ../../auth/login-admin.php'); exit; }
function h($v){return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');}
function money($v){return 'R$ '.number_format((float)$v,2,',','.');}
function mes_nome($ym){$n=['01'=>'Janeiro','02'=>'Fevereiro','03'=>'Março','04'=>'Abril','05'=>'Maio','06'=>'Junho','07'=>'Julho','08'=>'Agosto','09'=>'Setembro','10'=>'Outubro','11'=>'Novembro','12'=>'Dezembro']; if(!preg_match('/^\d{4}-\d{2}$/',$ym))return 'Todos os meses'; [$y,$m]=explode('-',$ym); return ($n[$m]??$m).' de '.$y;}
function texto_status($s){$s=strtolower((string)$s);$m=['pendente'=>'Pendente','em_andamento'=>'Em andamento','em-andamento'=>'Em andamento','finalizado'=>'Finalizado','concluida'=>'Concluído','concluido'=>'Concluído','cancelado'=>'Cancelado'];return $m[$s]??ucfirst(str_replace(['_','-'],' ',$s));}
function status_class($s){return 'st-'.str_replace('_','-',strtolower((string)$s));}
function primeiro_texto($a,$b='',$c=''){foreach([$a,$b,$c] as $v){if(trim((string)$v)!=='')return $v;}return '-';}
$competencia = isset($_GET['competencia']) && preg_match('/^\d{4}-\d{2}$/', $_GET['competencia']) ? $_GET['competencia'] : date('Y-m');
$clienteFiltro = isset($_GET['cliente_id']) ? (int)$_GET['cliente_id'] : 0;
$verTodos = isset($_GET['todos']) && $_GET['todos']==='1';
$clientes = $pdo->query('SELECT id,nome,logo,email FROM clientes ORDER BY nome ASC')->fetchAll(PDO::FETCH_ASSOC);
$meses = $pdo->query("SELECT DATE_FORMAT(data,'%Y-%m') competencia, COUNT(*) total, SUM(COALESCE(preco,0)) valor FROM solicitacoes WHERE preco IS NOT NULL AND preco > 0 GROUP BY DATE_FORMAT(data,'%Y-%m') ORDER BY competencia DESC")->fetchAll(PDO::FETCH_ASSOC);
$where = ' WHERE s.preco IS NOT NULL AND s.preco > 0 '; $params=[];
if(!$verTodos){$where .= " AND DATE_FORMAT(s.data,'%Y-%m') = ? "; $params[]=$competencia;}
if($clienteFiltro>0){$where .= ' AND s.cliente_id = ? '; $params[]=$clienteFiltro;}
$stmt=$pdo->prepare("SELECT s.*, c.nome cliente_nome, c.email cliente_email, c.logo cliente_logo FROM solicitacoes s LEFT JOIN clientes c ON c.id=s.cliente_id $where ORDER BY s.data DESC, s.id DESC");
$stmt->execute($params); $itens=$stmt->fetchAll(PDO::FETCH_ASSOC);
$total=$aberto=$finalizado=0;$qtdAbertos=$qtdFinalizados=0;$porCliente=[];$porMes=[];
foreach($itens as $i){$v=(float)($i['preco']??0);$total+=$v;$st=strtolower((string)($i['status']??''));if(in_array($st,['finalizado','concluida','concluido'],true)){$finalizado+=$v;$qtdFinalizados++;}else{$aberto+=$v;$qtdAbertos++;}$cn=$i['cliente_nome']?:'Cliente'; if(!isset($porCliente[$cn]))$porCliente[$cn]=['qtd'=>0,'valor'=>0];$porCliente[$cn]['qtd']++;$porCliente[$cn]['valor']+=$v;$ym=date('Y-m',strtotime($i['data']??'now')); if(!isset($porMes[$ym]))$porMes[$ym]=['qtd'=>0,'valor'=>0];$porMes[$ym]['qtd']++;$porMes[$ym]['valor']+=$v;}
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Financeiro Técnico - Infoservice</title><link rel="stylesheet" href="../../assets/css/helpdesk-pro.css"></head><body><div class="hd-page"><header class="hd-topbar hd-no-print"><div class="hd-container hd-topbar-inner"><div class="hd-brand"><div class="hd-brand-icon">💰</div><div><h1>Financeiro Técnico</h1><p>Valores e serviços prestados separados por mês, cliente e chamado.</p></div></div><div class="hd-user"><a class="hd-chip" href="dashboard.php">Dashboard</a><a class="hd-chip" href="mensagens.php">Mensagens <b data-chat-badge></b></a><a class="hd-chip" href="solicitacoes.php">Chamados</a><a class="hd-chip" href="../../auth/logout.php">Sair</a></div></div></header><main class="hd-main hd-financial-main"><div class="hd-container">
<section class="hd-card hd-card-pad hd-no-print hd-filter-card"><form method="GET" class="hd-form-grid hd-month-filter"><div class="hd-field"><label class="hd-label">Mês</label><select class="hd-input" name="competencia"><?php foreach($meses as $m): ?><option value="<?=h($m['competencia'])?>" <?=$competencia===$m['competencia']?'selected':''?>><?=h(mes_nome($m['competencia']))?> — <?=money($m['valor'])?></option><?php endforeach; ?></select></div><div class="hd-field"><label class="hd-label">Cliente</label><select class="hd-input" name="cliente_id"><option value="0">Todos os clientes</option><?php foreach($clientes as $c): ?><option value="<?=(int)$c['id']?>" <?=$clienteFiltro===(int)$c['id']?'selected':''?>><?=h($c['nome'])?></option><?php endforeach; ?></select></div><div class="hd-field"><label class="hd-label">Ação</label><div class="hd-actions"><button class="hd-btn hd-btn-primary" type="submit">🔎 Filtrar</button><a class="hd-btn hd-btn-outline" href="?todos=1<?= $clienteFiltro>0?'&cliente_id='.$clienteFiltro:'' ?>">Todos os meses</a><button class="hd-btn hd-btn-light" type="button" onclick="window.print()">🖨️ Imprimir</button></div></div></form></section>
<section class="hd-bank-statement hd-card"><div class="hd-bank-head"><div class="hd-bank-company"><div class="hd-bank-logo">IS</div><div><span>Relatório financeiro interno</span><h2><?=h($verTodos?'Todos os meses':mes_nome($competencia))?></h2><p><?= $clienteFiltro>0?'Cliente filtrado':'Todos os clientes' ?></p></div></div><div class="hd-bank-doc"><span>Documento</span><strong>ADM-<?=h($verTodos?'GERAL':str_replace('-','',$competencia))?></strong><small>Gerado em <?=date('d/m/Y H:i')?></small></div></div><div class="hd-bank-summary"><div><span>Total em serviços</span><strong><?=money($total)?></strong><small><?=count($itens)?> lançamento(s)</small></div><div><span>Aguardando conclusão</span><strong><?=money($aberto)?></strong><small><?=$qtdAbertos?> chamado(s)</small></div><div><span>Finalizados</span><strong><?=money($finalizado)?></strong><small><?=$qtdFinalizados?> chamado(s)</small></div></div></section>
<?php if($verTodos && count($porMes)>1): ?><section class="hd-card hd-card-pad hd-no-print"><div class="hd-section-head"><div><h2>Resumo por mês</h2><p>Clique em um mês para ver os detalhes.</p></div></div><div class="hd-month-grid"><?php foreach($porMes as $ym=>$r): ?><a class="hd-month-card" href="?competencia=<?=h($ym)?><?= $clienteFiltro>0?'&cliente_id='.$clienteFiltro:'' ?>"><span><?=h(mes_nome($ym))?></span><strong><?=money($r['valor'])?></strong><small><?=(int)$r['qtd']?> serviço(s)</small></a><?php endforeach; ?></div></section><?php endif; ?>
<section class="hd-card hd-card-pad hd-bank-table-card"><div class="hd-section-head"><div><h2>Serviços prestados detalhados</h2><p>Relatório técnico/financeiro para conferência e prestação de contas.</p></div><span class="hd-badge pr-media hd-no-print">Filtro mensal</span></div><?php if(!$itens): ?><div class="hd-empty">💰<strong>Nenhum serviço encontrado</strong>Altere o mês ou o cliente no filtro.</div><?php else: ?><div class="hd-table-wrap"><table class="hd-table hd-bank-table"><thead><tr><th>Data</th><th>Cliente</th><th>Documento</th><th>Serviço</th><th>Status</th><th>Valor</th></tr></thead><tbody><?php foreach($itens as $i): ?><?php $titulo=primeiro_texto($i['titulo']??'',mb_substr((string)($i['descricao']??''),0,90),'Serviço técnico');$protocolo=primeiro_texto($i['protocolo']??'','#'.($i['id']??''));$categoria=primeiro_texto($i['categoria']??'','Suporte técnico');$obs=trim((string)($i['observacao']??''));$desc=trim((string)($i['descricao']??'')); ?><tr><td class="hd-nowrap"><strong><?=date('d/m/Y',strtotime($i['data']??'now'))?></strong><small><?=date('H:i',strtotime($i['data']??'now'))?></small></td><td><strong><?=h($i['cliente_nome']??'-')?></strong><small><?=h($i['cliente_email']??'')?></small></td><td><strong><?=h($protocolo)?></strong><small>Chamado #<?=h($i['id']??'-')?></small></td><td><div class="hd-bank-service-title"><?=h($titulo)?></div><div class="hd-bank-service-meta">Categoria: <?=h($categoria)?><?php if(!empty($i['equipamento'])): ?> • Equipamento: <?=h($i['equipamento'])?><?php endif; ?><?php if(!empty($i['local_atendimento'])): ?> • Local: <?=h($i['local_atendimento'])?><?php endif; ?></div><?php if($desc): ?><div class="hd-bank-service-desc"><strong>Solicitação:</strong> <?=nl2br(h($desc))?></div><?php endif; ?><?php if($obs): ?><div class="hd-bank-service-desc"><strong>Execução técnica:</strong> <?=nl2br(h($obs))?></div><?php endif; ?></td><td><span class="hd-badge <?=h(status_class($i['status']??'pendente'))?>"><?=h(texto_status($i['status']??'pendente'))?></span></td><td class="hd-money-cell"><strong><?=money($i['preco']??0)?></strong></td></tr><?php endforeach; ?></tbody><tfoot><tr><td colspan="5">Total</td><td><?=money($total)?></td></tr></tfoot></table></div><?php endif; ?></section>
</div></main></div><script>window.HD_CHAT_CONFIG={endpointBase:'../../controllers/',chatUrl:'mensagens.php'};</script><script src="../../assets/js/live-chat-alerts.js"></script><script src="../../assets/js/helpdesk-pro.js"></script></body></html>
